        w.npcs = K.people; K.grid.forEach((r, y) => r.forEach((g, x) => { w.grid[y][x] = g; }));
        PETALS.length = 0; K.petals.forEach(p => PETALS.push(p)); HEROFEET.hc = K.feet.hc; HEROFEET.pc = K.feet.pc;
